previewCss:
.darma-loader-darma-b17-guillotine-cutter { --accent: var(--loader-color, #475569); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .66); position: relative; overflow: hidden; }
.darma-loader-darma-b17-guillotine-cutter .darma-loader-darma-b17-guillotine-cutter__bed { position: absolute; left: 0; right: 0; bottom: 4%; height: 20%; border-radius: 4px; background: linear-gradient(color-mix(in srgb, #fff 14%, var(--accent)), var(--accent)); }
.darma-loader-darma-b17-guillotine-cutter .darma-loader-darma-b17-guillotine-cutter__stack { position: absolute; left: 8%; bottom: 24%; width: 54%; height: 22%; border-radius: 2px; background: repeating-linear-gradient(color-mix(in srgb, #fff 90%, var(--accent)) 0 22%, color-mix(in srgb, #fff 62%, var(--accent)) 0 28%); box-shadow: 0 2px 4px color-mix(in srgb, #000 22%, transparent); }
.darma-loader-darma-b17-guillotine-cutter .darma-loader-darma-b17-guillotine-cutter__offcut { position: absolute; left: 62%; bottom: 24%; width: 18%; height: 22%; border-radius: 2px; background: repeating-linear-gradient(color-mix(in srgb, #fff 90%, var(--accent)) 0 22%, color-mix(in srgb, #fff 62%, var(--accent)) 0 28%); animation: darma-loader-darma-b17-guillotine-cutter-guillo-drop calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.5, 0, .7, 1) infinite; }
.darma-loader-darma-b17-guillotine-cutter .darma-loader-darma-b17-guillotine-cutter__blade { position: absolute; left: 58%; top: 0; width: 10%; height: 46%; background: linear-gradient(#e2e8f0, var(--accent-2)); clip-path: polygon(0 0, 100% 0, 100% 78%, 0 100%); transform-origin: 50% 0; animation: darma-loader-darma-b17-guillotine-cutter-guillo-chop calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes darma-loader-darma-b17-guillotine-cutter-guillo-chop { 0%, 22% { transform: translateY(0) rotate(0deg); } 40%, 50% { transform: translateY(84%) rotate(0deg); } 74%, 100% { transform: translateY(0) rotate(0deg); } }
@keyframes darma-loader-darma-b17-guillotine-cutter-guillo-drop { 0%, 42% { transform: translate(0, 0) rotate(0deg); opacity: 1; } 74% { transform: translate(30%, 90%) rotate(24deg); opacity: 1; } 84%, 92% { transform: translate(36%, 96%) rotate(26deg); opacity: 0; } 100% { transform: translate(0, 0) rotate(0deg); opacity: 1; } }

